/*!
 * shaking-soon-white.js — SHAKING SOON 3D 字（白色霧面），模型已內嵌，不使用圖片檔
 *
 * 用法：
 *   <div data-shaking-soon-white style="width:700px"></div>
 *   在容器後面引入：src="shaking-soon-white.js"
 *   data-color   自訂顏色，例如 #ff5fa2
 *   data-rotate  "true" 時可用滑鼠拖曳旋轉（預設固定不動）
 *   容器沒設高度時，依字的比例自動算高度。
 *
 * 手動呼叫：ShakingSoonWhite.mount('#box');
 * 3D 引擎：Three.js r170（從 CDN 載入）；可在引入前設定 window.SHAKING_SOON_THREE 改成自己的路徑。
 * 模型資料（MESH）格式：gzip 後 base64；內容 = uint32 頂點數, uint32 三角面數, float32[3] 最小值, float32[3] 最大值,
 *   uint16 量化頂點座標 (x,y,z)…, uint16 三角面索引…（little-endian）
 */
(function (global) {
  var MESH = '';
  var THREE_URL = global.SHAKING_SOON_THREE || 'https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.min.js';
  var RATIO = 2.3; // 寬 / 高

  var threePromise = null, geoPromise = null;
  function loadThree() {
    if (!threePromise) threePromise = global.ShakingSoonThree ? Promise.resolve(global.ShakingSoonThree) : import(THREE_URL);
    return threePromise;
  }

  function decode(THREE) {
    if (geoPromise) return geoPromise;
    geoPromise = (async function () {
      var bin = Uint8Array.from(atob(MESH), function (c) { return c.charCodeAt(0); });
      var stream = new Blob([bin]).stream().pipeThrough(new DecompressionStream('gzip'));
      var buf = await new Response(stream).arrayBuffer();
      var dv = new DataView(buf);
      var nv = dv.getUint32(0, true), nf = dv.getUint32(4, true);
      var lo = [], hi = [];
      for (var i = 0; i < 3; i++) { lo.push(dv.getFloat32(8 + i * 4, true)); hi.push(dv.getFloat32(20 + i * 4, true)); }
      var q = new Uint16Array(buf, 32, nv * 3);
      var idx = new Uint16Array(buf.slice(32 + nv * 6, 32 + nv * 6 + nf * 6));
      var pos = new Float32Array(nv * 3);
      for (var j = 0; j < nv; j++) {
        for (var k = 0; k < 3; k++) pos[j * 3 + k] = lo[k] + (q[j * 3 + k] / 65535) * (hi[k] - lo[k]);
      }
      var g = new THREE.BufferGeometry();
      g.setAttribute('position', new THREE.BufferAttribute(pos, 3));
      g.setIndex(new THREE.BufferAttribute(idx, 1));
      g.rotateY(-Math.PI / 2);
      g.center();
      g.computeVertexNormals();
      return g;
    })();
    return geoPromise;
  }

  function material(THREE, style, color) {
    if (style === 'cloud') {
      return new THREE.MeshStandardMaterial({ color: color || '#ffffff', roughness: 0.95, metalness: 0 });
    }
    // 壓克力漆感：有光澤但高光柔和、面積小
    return new THREE.MeshPhysicalMaterial({
      color: color || '#e8201c', roughness: 0.42, metalness: 0,
      specularIntensity: 0.55, clearcoat: 0.12, clearcoatRoughness: 0.5
    });
  }

  async function mount(target, opts) {
    opts = opts || {};
    var host = typeof target === 'string' ? document.querySelector(target) : target;
    if (!host) return null;
    var THREE = await loadThree();
    var geo = await decode(THREE);
    var style = 'cloud';

    var w = host.clientWidth || 600;
    var h = host.clientHeight || Math.round(w / RATIO);
    if (!host.clientHeight) host.style.height = h + 'px';

    var renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true, preserveDrawingBuffer: true });
    renderer.setPixelRatio(Math.min(global.devicePixelRatio || 1, 2));
    renderer.setSize(w, h);
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = style === 'cloud' ? 1.35 : 1.0;
    renderer.domElement.style.display = 'block';
    renderer.domElement.style.width = '100%';
    renderer.domElement.style.height = '100%';
    host.appendChild(renderer.domElement);

    var scene = new THREE.Scene();
    var cam = new THREE.PerspectiveCamera(22, w / h, 0.1, 100);

    // 燈光
    scene.add(new THREE.HemisphereLight(0xffffff, style === 'cloud' ? 0xc9d3e3 : 0x5a1a1a, style === 'cloud' ? 2.0 : 1.1));
    var key = new THREE.DirectionalLight(0xffffff, style === 'cloud' ? 1.6 : 2.2);
    key.position.set(-1.5, 2.5, 4);
    scene.add(key);
    var fill = new THREE.DirectionalLight(0xffffff, style === 'cloud' ? 0.8 : 0.9);
    fill.position.set(3, -1, 2);
    scene.add(fill);
    var rim = new THREE.DirectionalLight(0xffffff, 0.8);
    rim.position.set(0, 3, -3);
    scene.add(rim);

    var mesh = new THREE.Mesh(geo, material(THREE, style, opts.color));
    scene.add(mesh);

    function fit() {
      var cw = host.clientWidth || w, ch = host.clientHeight || h;
      renderer.setSize(cw, ch, false);
      cam.aspect = cw / ch;
      var box = new THREE.Box3().setFromObject(mesh), size = box.getSize(new THREE.Vector3());
      var vFov = cam.fov * Math.PI / 180;
      var distH = (size.y * 1.12) / 2 / Math.tan(vFov / 2);
      var distW = (size.x * 1.08) / 2 / Math.tan(vFov / 2) / cam.aspect;
      cam.position.set(0, 0, Math.max(distH, distW) + size.z / 2);
      cam.lookAt(0, 0, 0);
      cam.updateProjectionMatrix();
      render();
    }
    function render() { renderer.render(scene, cam); }

    if (opts.rotate) {
      var dragging = false, px = 0, py = 0;
      var el = renderer.domElement;
      el.style.cursor = 'grab';
      el.addEventListener('pointerdown', function (e) { dragging = true; px = e.clientX; py = e.clientY; el.setPointerCapture(e.pointerId); el.style.cursor = 'grabbing'; });
      el.addEventListener('pointerup', function () { dragging = false; el.style.cursor = 'grab'; });
      el.addEventListener('pointermove', function (e) {
        if (!dragging) return;
        mesh.rotation.y += (e.clientX - px) * 0.01;
        mesh.rotation.x += (e.clientY - py) * 0.01;
        px = e.clientX; py = e.clientY;
        render();
      });
    }

    if (global.ResizeObserver) new ResizeObserver(fit).observe(host);
    fit();
    return { renderer: renderer, scene: scene, mesh: mesh, render: render };
  }

  global.ShakingSoonWhite = { mount: mount };

  function auto() {
    var els = document.querySelectorAll('[data-shaking-soon-white]');
    for (var i = 0; i < els.length; i++) {
      var el = els[i];
      mount(el, {
        color: el.getAttribute('data-color') || undefined,
        rotate: el.getAttribute('data-rotate') === 'true'
      });
    }
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', auto);
  else auto();
})(window);
